import Phaser from 'phaser';
import {
  CHARACTERS,
  getOwnedCharacters,
  getSelectedCharacter,
  setSelectedCharacter,
  getDuplicateCount,
  getAwakeningLevel,
  type CharacterDef,
} from '../utils/character';
import { syncOwnedCharacters } from '../utils/gacha';

// 그리드 설정
const COLS = 3;
const CARD_W = 100;
const CARD_H = 120;
const GAP_X = 15;
const GAP_Y = 10;
const GRID_LEFT = (400 - (COLS * CARD_W + (COLS - 1) * GAP_X)) / 2; // 35px
