export interface FeverTimeConfig {
  /** 첫 피버 타임 발동 점수 */
  firstTriggerScore: number;
  /** 반복 간격 (점수 단위) */
  repeatInterval: number;
  /** 지속 시간 (밀리초) */
  duration: number;
