   373→/** 보유 목록과 서명을 함께 저장 (내부 전용) */
   374→function _saveOwned(list: string[]): void {
   375→  localStorage.setItem(OWNED_KEY, JSON.stringify(list));
   376→  localStorage.setItem(OWNED_SIG_KEY, _sign(list));
   377→}
