     1→import Phaser from 'phaser';
     2→import { STORY_LOGS, type StoryLog } from '../data/storyLogs';
     3→import { getUnlockedLogs } from '../utils/storyProgress';
     4→
     5→// ── 상수 ──────────────────────────────────────────────────────────────────────
     6→
     7→const ROW_H       = 72;   // 로그 행 높이
     8→const LIST_TOP    = 70;   // 목록 시작 Y
     9→const LIST_BOTTOM = 540;  // 목록 끝 Y
    10→const VISIBLE_H   = LIST_BOTTOM - LIST_TOP;
    11→
    12→// ── 씬 ───────────────────────────────────────────────────────────────────────
    13→
    14→export default class StoryLogScene extends Phaser.Scene {
    15→  // 스크롤
    16→  private scrollContainer!: Phaser.GameObjects.Container;
    17→  private maskShape!: Phaser.GameObjects.Graphics;
    18→  private scrollY        = 0;
    19→  private maxScrollY     = 0;
    20→  private isDragging     = false;
    21→  private dragStartY     = 0;
    22→  private dragStartScrollY = 0;
    23→
    24→  // 상세 패널
    25→  private detailPanel: Phaser.GameObjects.Container | null = null;
    26→
    27→  // 새로 해제된 로그 번호 (NEW 뱃지용)
    28→  private newLogs: number[] = [];
    29→
    30→  constructor() {
    31→    super('StoryLogScene');
    32→  }
    33→
    34→  init(data: { newLogs?: number[] }) {
    35→    this.newLogs = data.newLogs ?? [];
    36→    this.scrollY = 0;
    37→    this.detailPanel = null;
    38→  }
    39→
    40→  preload() {
    41→    if (!this.textures.exists('background2')) {
    42→      this.load.image('background2', 'assets/backgrounds/background2.webp');
    43→    }
    44→
    45→    // 영상이 있는 로그만 로드
    46→    for (const log of STORY_LOGS) {
    47→      if (log.videoKey && log.videoPath && !this.sys.game.cache.video.has(log.videoKey)) {
    48→        this.load.video(log.videoKey, log.videoPath, true);
    49→      }
    50→    }
    51→  }
    52→
    53→  create() {
    54→    const unlockedIds = getUnlockedLogs();
    55→
    56→    // 배경
    57→    this.add.image(200, 300, 'background2').setDisplaySize(400, 600);
    58→    this.add.rectangle(200, 300, 400, 600, 0x000000, 0.75);
    59→
    60→    // 타이틀 (고정)
    61→    this.add.text(200, 35, '이야기', {
    62→      fontSize: '26px',
    63→      color: '#fff',
    64→      fontStyle: 'bold',
    65→      stroke: '#000',
    66→      strokeThickness: 5,
    67→    }).setOrigin(0.5).setDepth(10);
    68→
    69→    // 해제 현황 (고정)
    70→    this.add.text(200, 57, `${unlockedIds.length} / ${STORY_LOGS.length} 해제`, {
    71→      fontSize: '13px',
    72→      color: '#aaaaaa',
    73→    }).setOrigin(0.5).setDepth(10);
    74→
    75→    // 마스크
    76→    this.maskShape = this.make.graphics({ x: 0, y: 0 });
    77→    this.maskShape.fillRect(0, LIST_TOP, 400, VISIBLE_H);
    78→    const mask = this.maskShape.createGeometryMask();
    79→    this.events.once('shutdown', () => { this.maskShape.destroy(); });
    80→
    81→    // 스크롤 컨테이너
    82→    this.scrollContainer = this.add.container(0, LIST_TOP);
    83→    this.scrollContainer.setMask(mask);
    84→
    85→    // 로그 행 생성
    86→    let currentY = 8;
    87→    for (const log of STORY_LOGS) {
    88→      const isUnlocked = unlockedIds.includes(log.id);
    89→      const isNew      = this.newLogs.includes(log.id);
    90→      this.createLogRow(log, currentY, isUnlocked, isNew);
    91→      currentY += ROW_H + 6;
    92→    }
    93→
    94→    this.maxScrollY = Math.max(0, currentY - VISIBLE_H);
    95→
    96→    this.setupScrollInput();
    97→    this.createBackButton();
    98→  }
    99→
   100→  // ── 행 생성 ────────────────────────────────────────────────────────────────
   101→
   102→  private createLogRow(
   103→    log: StoryLog,
   104→    y: number,
   105→    isUnlocked: boolean,
   106→    isNew: boolean,
   107→  ) {
   108→    const bg = this.add.rectangle(200, y + ROW_H / 2, 370, ROW_H - 4, 0x1a1a2e, 1);
   109→    bg.setStrokeStyle(1, isUnlocked ? 0x4466cc : 0x333355);
   110→    this.scrollContainer.add(bg);
   111→
   112→    // 번호 라벨
   113→    const idLabel = this.add.text(24, y + ROW_H / 2, `#${String(log.id).padStart(3, '0')}`, {
   114→      fontSize: '13px',
   115→      color: isUnlocked ? '#88aaff' : '#445566',
   116→      fontStyle: 'bold',
   117→    }).setOrigin(0, 0.5);
   118→    this.scrollContainer.add(idLabel);
   119→
   120→    if (isUnlocked) {
   121→      // 제목
   122→      const title = this.add.text(70, y + ROW_H / 2 - 10, log.title, {
   123→        fontSize: '17px',
   124→        color: '#ffffff',
   125→        fontStyle: 'bold',
   126→        stroke: '#000',
   127→        strokeThickness: 3,
   128→      }).setOrigin(0, 0.5);
   129→      this.scrollContainer.add(title);
   130→
   131→      // 힌트 (작게)
   132→      const hint = this.add.text(70, y + ROW_H / 2 + 11, log.unlockHint, {
   133→        fontSize: '11px',
   134→        color: '#778899',
   135→      }).setOrigin(0, 0.5);
   136→      this.scrollContainer.add(hint);
   137→
   138→      // 영상 아이콘 (영상 있는 로그)
   139→      if (log.videoKey) {
   140→        const vidIcon = this.add.text(350, y + ROW_H / 2, '▶', {
   141→          fontSize: '14px',
   142→          color: '#aaddff',
   143→        }).setOrigin(0.5);
   144→        this.scrollContainer.add(vidIcon);
   145→      }
   146→
   147→      // NEW 뱃지
   148→      if (isNew) {
   149→        const badgeBg = this.add.rectangle(348, y + 14, 36, 18, 0xff3333)
   150→          .setStrokeStyle(1, 0xcc0000);
   151→        const badgeText = this.add.text(348, y + 14, 'NEW', {
   152→          fontSize: '11px',
   153→          color: '#fff',
   154→          fontStyle: 'bold',
   155→        }).setOrigin(0.5);
   156→        this.scrollContainer.add(badgeBg);
   157→        this.scrollContainer.add(badgeText);
   158→      }
   159→
   160→      // 탭 가능 영역
   161→      bg.setInteractive({ useHandCursor: true });
   162→      bg.on('pointerover', () => bg.setFillStyle(0x2d2d5e));
   163→      bg.on('pointerout',  () => bg.setFillStyle(0x1a1a2e));
   164→      bg.on('pointerup', () => {
   165→        if (!this.isDragging) this.showDetail(log);
   166→      });
   167→
   168→    } else {
   169→      // 잠금 상태: 자물쇠 + ???
   170→      const lock = this.add.text(70, y + ROW_H / 2 - 9, '🔒 ???', {
   171→        fontSize: '16px',
   172→        color: '#445566',
   173→      }).setOrigin(0, 0.5);
   174→      this.scrollContainer.add(lock);
   175→
   176→      const hint = this.add.text(70, y + ROW_H / 2 + 12, log.unlockHint, {
   177→        fontSize: '11px',
   178→        color: '#445566',
   179→      }).setOrigin(0, 0.5);
   180→      this.scrollContainer.add(hint);
   181→    }
   182→  }
   183→
   184→  // ── 상세 패널 ─────────────────────────────────────────────────────────────
   185→
   186→  private showDetail(log: StoryLog) {
   187→    if (this.detailPanel) return;
   188→
   189→    const overlay = this.add.rectangle(200, 300, 400, 600, 0x000000, 0.85)
   190→      .setDepth(200)
   191→      .setInteractive();  // 클릭 관통 방지
   192→
   193→    const CARD_W = 340;
   194→    const hasVideo = !!log.videoKey;
   195→    const VIDEO_H  = hasVideo ? 190 : 0;
   196→    const TEXT_PAD = 20;
   197→
   198→    // 텍스트 높이 사전 측정
   199→    const measure = this.add.text(0, -999, log.text, {
   200→      fontSize: '15px',
   201→      color: '#fff',
   202→      wordWrap: { width: CARD_W - TEXT_PAD * 2 },
   203→      lineSpacing: 6,
   204→    });
   205→    const textH = measure.height;
   206→    measure.destroy();
