import Phaser from 'phaser';
import { STORY_LOGS, type StoryLog } from '../data/storyLogs';
import { getUnlockedLogs } from '../utils/storyProgress';

// ── 상수 ──────────────────────────────────────────────────────────────────────

const ROW_H       = 72;   // 로그 행 높이
const LIST_TOP    = 70;   // 목록 시작 Y
const LIST_BOTTOM = 540;  // 목록 끝 Y
const VISIBLE_H   = LIST_BOTTOM - LIST_TOP;

// ── 씬 ───────────────────────────────────────────────────────────────────────

export default class StoryLogScene extends Phaser.Scene {
  // 스크롤
  private scrollContainer!: Phaser.GameObjects.Container;
  private maskShape!: Phaser.GameObjects.Graphics;
  private scrollY        = 0;
  private maxScrollY     = 0;
  private isDragging     = false;
  private dragStartY     = 0;
  private dragStartScrollY = 0;

  // 상세 패널
  private detailPanel: Phaser.GameObjects.Container | null = null;

  // 새로 해제된 로그 번호 (NEW 뱃지용)
  private newLogs: number[] = [];

  // 로그별 텍스트 높이 캐시 (id → height)
  private textHeightCache = new Map<number, number>();

  constructor() {
    super('StoryLogScene');
  }

  init(data: { newLogs?: number[] }) {
    this.newLogs = data.newLogs ?? [];
    this.scrollY = 0;
    this.detailPanel = null;
  }

  preload() {
    if (!this.textures.exists('background2')) {
      this.load.image('background2', 'assets/backgrounds/background2.webp');
    }

    // 영상이 있는 로그만 로드
    for (const log of STORY_LOGS) {
      if (log.videoKey && log.videoPath && !this.cache.video.exists(log.videoKey)) {
        this.load.video(log.videoKey, log.videoPath, true);
      }
    }
  }

  create() {
    const unlockedIds = getUnlockedLogs();

    // 배경
    this.add.image(200, 300, 'background2').setDisplaySize(400, 600);
    this.add.rectangle(200, 300, 400, 600, 0x000000, 0.75);

    // 타이틀 (고정)
    this.add.text(200, 35, '이야기', {
      fontSize: '26px',
      color: '#fff',
      fontStyle: 'bold',
      stroke: '#000',
      strokeThickness: 5,
    }).setOrigin(0.5).setDepth(10);

    // 해제 현황 (고정)
    this.add.text(200, 57, `${unlockedIds.length} / ${STORY_LOGS.length} 해제`, {
      fontSize: '13px',
      color: '#aaaaaa',
    }).setOrigin(0.5).setDepth(10);

    // 마스크
    this.maskShape = this.make.graphics({ x: 0, y: 0 });
    this.maskShape.fillRect(0, LIST_TOP, 400, VISIBLE_H);
    const mask = this.maskShape.createGeometryMask();
    this.events.once('shutdown', () => { this.maskShape.destroy(); });

    // 스크롤 컨테이너
    this.scrollContainer = this.add.container(0, LIST_TOP);
    this.scrollContainer.setMask(mask);

    // 로그 행 생성
    let currentY = 8;
    for (const log of STORY_LOGS) {
      const isUnlocked = unlockedIds.includes(log.id);
      const isNew      = this.newLogs.includes(log.id);
      this.createLogRow(log, currentY, isUnlocked, isNew);
      currentY += ROW_H + 6;
    }

    this.maxScrollY = Math.max(0, currentY - VISIBLE_H);

    this.setupScrollInput();
    this.createBackButton();
  }

  // ── 행 생성 ────────────────────────────────────────────────────────────────

  private createLogRow(
    log: StoryLog,
    y: number,
    isUnlocked: boolean,
    isNew: boolean,
  ) {
    const bg = this.add.rectangle(200, y + ROW_H / 2, 370, ROW_H - 4, 0x1a1a2e, 1);
    bg.setStrokeStyle(1, isUnlocked ? 0x4466cc : 0x333355);
    this.scrollContainer.add(bg);

    // 번호 라벨
    const idLabel = this.add.text(24, y + ROW_H / 2, `#${String(log.id).padStart(3, '0')}`, {
      fontSize: '13px',
      color: isUnlocked ? '#88aaff' : '#445566',
      fontStyle: 'bold',
    }).setOrigin(0, 0.5);
    this.scrollContainer.add(idLabel);

    if (isUnlocked) {
      // 제목
      const title = this.add.text(70, y + ROW_H / 2 - 10, log.title, {
        fontSize: '17px',
        color: '#ffffff',
        fontStyle: 'bold',
        stroke: '#000',
        strokeThickness: 3,
      }).setOrigin(0, 0.5);
      this.scrollContainer.add(title);

      // 힌트 (작게)
      const hint = this.add.text(70, y + ROW_H / 2 + 11, log.unlockHint, {
        fontSize: '11px',
        color: '#778899',
      }).setOrigin(0, 0.5);
      this.scrollContainer.add(hint);

      // 영상 아이콘 (영상 있는 로그)
      if (log.videoKey) {
        const vidIcon = this.add.text(350, y + ROW_H / 2, '▶', {
          fontSize: '14px',
          color: '#aaddff',
        }).setOrigin(0.5);
        this.scrollContainer.add(vidIcon);
      }

      // NEW 뱃지
      if (isNew) {
        const badgeBg = this.add.rectangle(348, y + 14, 36, 18, 0xff3333)
          .setStrokeStyle(1, 0xcc0000);
        const badgeText = this.add.text(348, y + 14, 'NEW', {
          fontSize: '11px',
          color: '#fff',
          fontStyle: 'bold',
        }).setOrigin(0.5);
        this.scrollContainer.add(badgeBg);
        this.scrollContainer.add(badgeText);
      }

      // 탭 가능 영역
      bg.setInteractive({ useHandCursor: true });
      bg.on('pointerover', () => bg.setFillStyle(0x2d2d5e));
      bg.on('pointerout',  () => bg.setFillStyle(0x1a1a2e));
      bg.on('pointerup', () => {
        if (!this.isDragging) this.showDetail(log);
      });

    } else {
      // 잠금 상태: 자물쇠 + ???
      const lock = this.add.text(70, y + ROW_H / 2 - 9, '🔒 ???', {
        fontSize: '16px',
        color: '#445566',
      }).setOrigin(0, 0.5);
      this.scrollContainer.add(lock);

      const hint = this.add.text(70, y + ROW_H / 2 + 12, log.unlockHint, {
        fontSize: '11px',
        color: '#445566',
      }).setOrigin(0, 0.5);
      this.scrollContainer.add(hint);
    }
  }

  // ── 상세 패널 ─────────────────────────────────────────────────────────────

  private showDetail(log: StoryLog) {
    if (this.detailPanel) return;

    const overlay = this.add.rectangle(200, 300, 400, 600, 0x000000, 0.85)
      .setDepth(200)
      .setInteractive();  // 클릭 관통 방지

    const CARD_W = 340;
    const hasVideo = !!log.videoKey;
    const VIDEO_H  = hasVideo ? 190 : 0;
    const TEXT_PAD = 20;

    // 텍스트 높이 사전 측정
    const measure = this.add.text(0, -999, log.text, {
      fontSize: '15px',
      color: '#fff',
      wordWrap: { width: CARD_W - TEXT_PAD * 2 },
      lineSpacing: 6,
    });
    const textH = measure.height;
    measure.destroy();

    const CARD_H = Math.min(520, 60 + VIDEO_H + (hasVideo ? 16 : 0) + textH + 60);
    const cardY  = 300;

    const card = this.add.rectangle(200, cardY, CARD_W, CARD_H, 0x0d0d1a, 1)
      .setStrokeStyle(2, 0x4466cc)
      .setDepth(201);

    // 헤더
    const header = this.add.text(200, cardY - CARD_H / 2 + 22, `#${String(log.id).padStart(3, '0')}  ${log.title}`, {
      fontSize: '17px',
      color: '#88aaff',
      fontStyle: 'bold',
      stroke: '#000',
      strokeThickness: 3,
    }).setOrigin(0.5, 0.5).setDepth(202);

    // 구분선
    const divider = this.add.rectangle(200, cardY - CARD_H / 2 + 42, CARD_W - 24, 1, 0x4466cc, 0.5)
      .setDepth(202);

    const contentTop = cardY - CARD_H / 2 + 52;

    const elements: Phaser.GameObjects.GameObject[] = [overlay, card, header, divider];

    // 영상
    let videoBottom = contentTop;
    if (hasVideo && log.videoKey) {
      const vid = this.add.video(200, contentTop + VIDEO_H / 2, log.videoKey)
        .setDepth(202);
      vid.setDisplaySize(CARD_W - 8, VIDEO_H - 8);
      vid.play(true);
      elements.push(vid);
      videoBottom = contentTop + VIDEO_H + 16;
    }

    // 본문
    const body = this.add.text(200, videoBottom, log.text, {
      fontSize: '15px',
      color: '#dddddd',
      wordWrap: { width: CARD_W - TEXT_PAD * 2 },
      lineSpacing: 6,
      align: 'center',
    }).setOrigin(0.5, 0).setDepth(202);
    elements.push(body);

    // ✕ 닫기 버튼
    const closeBtn = this.add.text(200, cardY + CARD_H / 2 - 22, '닫기', {
      fontSize: '15px',
      color: '#aaaaaa',
      stroke: '#000',
      strokeThickness: 3,
    }).setOrigin(0.5).setDepth(202).setInteractive({ useHandCursor: true });
    closeBtn.on('pointerover', () => closeBtn.setColor('#ffffff'));
    closeBtn.on('pointerout',  () => closeBtn.setColor('#aaaaaa'));
    closeBtn.on('pointerdown', () => this.closeDetail());
    elements.push(closeBtn);

    this.detailPanel = this.add.container(0, 0, elements).setDepth(200);
  }

  private closeDetail() {
    if (!this.detailPanel) return;
    this.detailPanel.destroy(true);
    this.detailPanel = null;
  }

  // ── 스크롤 ────────────────────────────────────────────────────────────────

  private setupScrollInput() {
    this.input.on('pointerdown', (p: Phaser.Input.Pointer) => {
      if (this.detailPanel) return;
      if (p.y > LIST_TOP && p.y < LIST_BOTTOM) {
        this.isDragging     = false;
        this.dragStartY     = p.y;
        this.dragStartScrollY = this.scrollY;
      }
    });

    this.input.on('pointermove', (p: Phaser.Input.Pointer) => {
      if (this.detailPanel) return;
      if (!p.isDown) return;
      const delta = Math.abs(p.y - this.dragStartY);
      if (delta > 6) this.isDragging = true;
      if (!this.isDragging) return;
      this.scrollY = Phaser.Math.Clamp(
        this.dragStartScrollY + (this.dragStartY - p.y),
        0,
        this.maxScrollY,
      );
      this.scrollContainer.y = LIST_TOP - this.scrollY;
    });

    this.input.on('pointerup', () => {
      this.time.delayedCall(50, () => { this.isDragging = false; });
    });

    this.input.on('wheel', (_p: Phaser.Input.Pointer, _o: Phaser.GameObjects.GameObject[], _dx: number, dy: number) => {
      if (this.detailPanel) return;
      this.scrollY = Phaser.Math.Clamp(this.scrollY + dy * 0.5, 0, this.maxScrollY);
      this.scrollContainer.y = LIST_TOP - this.scrollY;
    });
  }

  // ── 뒤로가기 ──────────────────────────────────────────────────────────────

  private createBackButton() {
    const btn = this.add.rectangle(200, 564, 150, 40, 0xffffff).setStrokeStyle(3, 0x000000).setDepth(10);
    const txt = this.add.text(200, 564, '← 뒤로가기', {
      fontSize: '18px',
      color: '#000',
      fontStyle: 'bold',
    }).setOrigin(0.5).setDepth(10);

    [btn, txt].forEach(el => {
      el.setInteractive({ useHandCursor: true });
      el.on('pointerover', () => btn.setFillStyle(0xffff99));
      el.on('pointerout',  () => btn.setFillStyle(0xffffff));
      el.on('pointerdown', () => {
        if (this.detailPanel) { this.closeDetail(); return; }
        this.scene.start('ModeSelectScene');
      });
    });
  }
}

