     1→/**
     2→ * 스토리 진행도 관리
     3→ *
     4→ * - 누적 통계 (달린 거리, 토파즈 수집, 치비 플레이 횟수, SKOR 획득)를 localStorage에 djb2 서명으로 저장
     5→ * - 잠금 해제 조건을 체크하고 새로 열린 로그 번호를 반환
     6→ * - 서명 불일치 시 변조로 판단해 초기값으로 초기화
     7→ */
     8→
     9→import { getOwnedCharacters, CHARACTERS } from './character';
    10→
    11→// ── 타입 ──────────────────────────────────────────────────────────────────────
    12→
    13→export interface StoryStats {
    14→  totalDistance: number;       // 누적 달린 거리 (m, score 1점 = 1m)
    15→  totalTopazCollected: number; // 누적 토파즈똥 수집 수
    16→  chibiPlayCount: number;      // 치비 캐릭터로 플레이한 횟수
    17→  totalSkorEarned: number;     // 누적 SKOR 획득량
    18→}
    19→
    20→// ── localStorage 키 / Salt ────────────────────────────────────────────────────
    21→
    22→const STATS_KEY     = 'storyStats';
    23→const STATS_SIG_KEY = 'storyStatsSig';
    24→const LOGS_KEY      = 'storyLogs';
    25→const LOGS_SIG_KEY  = 'storyLogsSig';
    26→
    27→const _STATS_SALT = 'ddong-story-stats-\u0076\u0031';
    28→const _LOGS_SALT  = 'ddong-story-logs-\u0076\u0031';
    29→
    30→// ── djb2 해시 ────────────────────────────────────────────────────────────────
    31→
    32→function _djb2(str: string): string {
    33→  let h = 5381;
    34→  for (let i = 0; i < str.length; i++) h = (((h << 5) + h) ^ str.charCodeAt(i)) >>> 0;
    35→  return h.toString(36);
    36→}
    37→
    38→function _signStats(s: StoryStats): string {
    39→  return _djb2(
    40→    `${s.totalDistance}:${s.totalTopazCollected}:${s.chibiPlayCount}:${s.totalSkorEarned}` + _STATS_SALT
    41→  );
    42→}
    43→
    44→function _signLogs(logs: number[]): string {
    45→  return _djb2([...logs].sort((a, b) => a - b).join(',') + _LOGS_SALT);
    46→}
    47→
    48→// ── 읽기 / 쓰기 ──────────────────────────────────────────────────────────────
    49→
    50→const _DEFAULT_STATS: StoryStats = {
    51→  totalDistance: 0,
    52→  totalTopazCollected: 0,
    53→  chibiPlayCount: 0,
    54→  totalSkorEarned: 0,
    55→};
    56→
    57→function _loadStats(): StoryStats {
    58→  try {
    59→    const raw = localStorage.getItem(STATS_KEY);
    60→    const sig = localStorage.getItem(STATS_SIG_KEY);
    61→    if (!raw) return { ..._DEFAULT_STATS };
    62→
    63→    const stats = JSON.parse(raw) as StoryStats;
    64→    if (!sig) {
    65→      // 서명 없음 → 기존 데이터 신뢰 후 서명 최초 발급
    66→      _saveStats(stats);
    67→      return stats;
    68→    }
    69→    if (sig !== _signStats(stats)) {
    70→      // 서명 불일치 → 변조, 초기화
    71→      _saveStats({ ..._DEFAULT_STATS });
    72→      return { ..._DEFAULT_STATS };
    73→    }
    74→    return stats;
    75→  } catch {
    76→    return { ..._DEFAULT_STATS };
    77→  }
    78→}
    79→
    80→function _saveStats(stats: StoryStats): void {
    81→  localStorage.setItem(STATS_KEY, JSON.stringify(stats));
    82→  localStorage.setItem(STATS_SIG_KEY, _signStats(stats));
    83→}
    84→
    85→function _loadLogs(): number[] {
    86→  try {
    87→    const raw = localStorage.getItem(LOGS_KEY);
    88→    const sig = localStorage.getItem(LOGS_SIG_KEY);
    89→    if (!raw) return [];
    90→
    91→    const logs = JSON.parse(raw) as number[];
    92→    if (!sig) {
    93→      _saveLogs(logs);
    94→      return logs;
    95→    }
    96→    if (sig !== _signLogs(logs)) {
    97→      _saveLogs([]);
    98→      return [];
    99→    }
   100→    return logs;
   101→  } catch {
   102→    return [];
   103→  }
   104→}
   105→
   106→function _saveLogs(logs: number[]): void {
   107→  localStorage.setItem(LOGS_KEY, JSON.stringify(logs));
   108→  localStorage.setItem(LOGS_SIG_KEY, _signLogs(logs));
   109→}
   110→
   111→// ── 잠금 해제 조건 체크 ────────────────────────────────────────────────────────
   112→
   113→/**
   114→ * 현재 stats + 보유 캐릭터 기준으로 잠금 해제 가능한 로그를 체크.
   115→ * @returns 새로 잠금 해제된 로그 번호 배열
   116→ */
   117→function _checkConditions(stats: StoryStats, unlockedLogs: number[]): number[] {
   118→  const ownedCount = getOwnedCharacters().length;
   119→  const newLogs: number[] = [];
   120→
   121→  const unlock = (logNum: number, condition: boolean) => {
   122→    if (condition && !unlockedLogs.includes(logNum)) {
   123→      newLogs.push(logNum);
   124→    }
   125→  };
   126→
   127→  unlock(1,  ownedCount >= 2);                            // 첫 번째 뽑기 완료
   128→  unlock(2,  ownedCount >= 2);                            // 캐릭터 2명 보유
   129→  unlock(3,  stats.totalDistance >= 500);                 // 달린 거리 500m
   130→  unlock(4,  stats.totalSkorEarned >= 100);               // SKOR 100 누적 획득
   131→  unlock(5,  ownedCount >= 3);                            // 캐릭터 3명 보유
   132→  unlock(8,  stats.totalDistance >= 5000);                // 달린 거리 5000m
   133→  unlock(9,  ownedCount >= 5);                            // 캐릭터 5명 보유
   134→  unlock(10, stats.chibiPlayCount >= 50);                 // 치비 50회 플레이
   135→  unlock(11, stats.totalTopazCollected >= 30);            // 토파즈 30개 수집
   136→  unlock(12, stats.totalDistance >= 10000);               // 달린 거리 10000m
   137→  unlock(13, ownedCount >= CHARACTERS.length);            // 전체 캐릭터 수집
   138→
   139→  return newLogs;
   140→}
   141→
   142→function _applyNewLogs(newLogs: number[], currentLogs: number[]): void {
   143→  if (newLogs.length === 0) return;
   144→  _saveLogs([...currentLogs, ...newLogs]);
   145→}
   146→
   147→// ── 공개 API ──────────────────────────────────────────────────────────────────
   148→
   149→/**
   150→ * 게임 세션 완료 시 호출 (게임오버 시점).
   151→ * score를 달린 거리(m)로 사용.
   152→ * @returns 새로 잠금 해제된 로그 번호 배열
   153→ */
   154→export function recordGameSession(
   155→  score: number,
   156→  topazCollected: number,
   157→  wasChibi: boolean,
   158→): number[] {
   159→  const stats = _loadStats();
   160→  const logs  = _loadLogs();
   161→
   162→  stats.totalDistance       += score;
   163→  stats.totalTopazCollected += topazCollected;
   164→  if (wasChibi) stats.chibiPlayCount += 1;
   165→
   166→  _saveStats(stats);
   167→
   168→  const newLogs = _checkConditions(stats, logs);
   169→  _applyNewLogs(newLogs, logs);
   170→  return newLogs;
   171→}
   172→
   173→/**
   174→ * SKOR 획득 시 호출 (skor-submit 응답의 totalSkorAdded).
   175→ * @returns 새로 잠금 해제된 로그 번호 배열
   176→ */
   177→export function recordSkorEarned(amount: number): number[] {
   178→  if (amount <= 0) return [];
   179→
   180→  const stats = _loadStats();
   181→  const logs  = _loadLogs();
   182→
   183→  stats.totalSkorEarned += amount;
   184→  _saveStats(stats);
   185→
   186→  const newLogs = _checkConditions(stats, logs);
   187→  _applyNewLogs(newLogs, logs);
   188→  return newLogs;
   189→}
   190→
   191→/**
   192→ * 뽑기/캐릭터 획득 후 호출 (보유 수 기반 조건 체크).
   193→ * @returns 새로 잠금 해제된 로그 번호 배열
   194→ */
   195→export function checkOwnershipConditions(): number[] {
   196→  const stats = _loadStats();
   197→  const logs  = _loadLogs();
   198→
   199→  const newLogs = _checkConditions(stats, logs);
   200→  _applyNewLogs(newLogs, logs);
   201→  return newLogs;
   202→}
   203→
   204→/** 현재 잠금 해제된 로그 번호 목록 반환 */
   205→export function getUnlockedLogs(): number[] {
   206→  return _loadLogs();
   207→}
   208→
   209→/** 누적 통계 반환 (디버그/UI 표시용) */
   210→export function getStoryStats(): StoryStats {
   211→  return _loadStats();
   212→}
