     1→/**
     2→ * djb2 해시 — localStorage 무결성 서명에 사용하는 경량 해시.
     3→ * 모듈 로드 시점에 결정론적으로 계산되므로 런타임 조작 불가.
     4→ */
     5→export function djb2(str: string): string {
     6→  let h = 5381;
     7→  for (let i = 0; i < str.length; i++) h = (((h << 5) + h) ^ str.charCodeAt(i)) >>> 0;
     8→  return h.toString(36);
     9→}
