    32→const CORE_HIGHLIGHT_R  = 1.2;   // 하이라이트 스팟 반지름
    33→
    34→export default class CharacterSelectScene extends Phaser.Scene {
    35→  private selectedId: string = 'chibi';
    36→  private ownedIds: string[] = [];
